/**
 * The redirect policy. Mirrors `engine_ports::RedirectPolicy`.
 */
sealed class RedirectPolicy {
    
    /**
     * No redirects.
     */
    object None : RedirectPolicy()
    
    
    /**
     * At most this many hops.
     */
    data class Max(
        val v1: kotlin.UInt) : RedirectPolicy() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRedirectPolicy : FfiConverterRustBuffer<RedirectPolicy>{
    override fun read(buf: ByteBuffer): RedirectPolicy {
        return when(buf.getInt()) {
            1 -> RedirectPolicy.None
            2 -> RedirectPolicy.Max(
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RedirectPolicy) = when(value) {
        is RedirectPolicy.None -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RedirectPolicy.Max -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: RedirectPolicy, buf: ByteBuffer) {
        when(value) {
            is RedirectPolicy.None -> {
                buf.putInt(1)
                Unit
            }
            is RedirectPolicy.Max -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * The error the SDK's foreign implementations answer with.
 */
sealed class SdkException: kotlin.Exception() {
    
    /**
     * The network refused.
     */
    class NetworkRefused(
        ) : SdkException() {
        override val message
            get() = ""
    }
    
    /**
     * The transport failed.
     */
    class Transport(
        
        val v1: kotlin.String
        ) : SdkException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The host declined.
     */
    class Declined(
        ) : SdkException() {
        override val message
            get() = ""
    }
    
    /**
     * The host cannot answer.
     */
    class Cannot(
        
        val v1: kotlin.String
        ) : SdkException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * An internal error.
     */
    class Internal(
        ) : SdkException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SdkException> {
        override fun lift(error_buf: RustBuffer.ByValue): SdkException = FfiConverterTypeSdkError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSdkError : FfiConverterRustBuffer<SdkException> {
    override fun read(buf: ByteBuffer): SdkException {
        

        return when(buf.getInt()) {
            1 -> SdkException.NetworkRefused()
            2 -> SdkException.Transport(
                FfiConverterString.read(buf),
                )
            3 -> SdkException.Declined()
            4 -> SdkException.Cannot(
                FfiConverterString.read(buf),
                )
            5 -> SdkException.Internal()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SdkException): ULong {
        return when(value) {
            is SdkException.NetworkRefused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SdkException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is SdkException.Declined -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SdkException.Cannot -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is SdkException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: SdkException, buf: ByteBuffer) {
        when(value) {
            is SdkException.NetworkRefused -> {
                buf.putInt(1)
                Unit
            }
            is SdkException.Transport -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is SdkException.Declined -> {
                buf.putInt(3)
                Unit
            }
            is SdkException.Cannot -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is SdkException.Internal -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * The wallet host: the sub-flows the engine asks the wallet's user for.
 * The Kotlin/Swift implementation is the adapter's
 * `engine_ports::Host`.
 */
public interface Host {
    
    /**
     * Asks the host to sign the given input.
     */
    suspend fun `requestSign`(`params`: SignParams): SignResult
    
    /**
     * Asks the host to match the wallet's credentials against the DCQL
     * query and select what to present. An empty answer means nothing
     * matched: the flow ends there.
     */
    suspend fun `requestMatch`(`params`: MatchParams): MatchResult
    
    /**
     * Asks the host to construct and sign the VP token for the
     * selected credentials — the wallet's presentation formats and
     * key custody live in the host.
     */
    suspend fun `requestVp`(`params`: VpParams): VpResult
    
    /**
     * Asks the host for a client-held DPoP proof; the engine falls
     * back to its own key when the host cannot answer.
     */
    suspend fun `requestDpopProof`(`params`: DpopProofParams): DpopProofResult
    
    /**
     * Asks the host's user for consent.
     */
    suspend fun `requestConsent`(`params`: ConsentParams): ConsentResult
    
    /**
     * Asks the host's user for the transaction code.
     */
    suspend fun `requestTxCode`(`flowId`: kotlin.String): kotlin.String
    
    /**
     * Opens the authorization URL in the host's browser.
     */
    suspend fun `openAuthorization`(`flowId`: kotlin.String, `url`: kotlin.String)
    
    /**
     * Asks the host for the public JWK of a named signing key, so the
     * engine can identify the key in the proof headers it builds. Keys
     * always live in the app; the engine only ever sees the public
     * JWK. A refusal keeps the flows working without key identification.
     */
    suspend fun `requestSigningKey`(`params`: SigningKeyParams): SigningKeyResult
    
    /**
     * Asks the host for a client attestation (a Wallet Instance
     * Attestation and its proof of possession), when the AS demands
     * one. A refusal continues without client attestation.
     */
    suspend fun `requestAttestation`(`params`: AttestationParams): AttestationResult
    
    /**
     * Asks the host's user to pick one of the offered credential
     * configurations, when the offer names more than one. A refusal
     * fails the flow closed (exactly one configuration is
     * auto-selected and never asked).
     */
    suspend fun `requestCredentialSelection`(`params`: CredentialSelectionParams): CredentialSelectionResult
    
    /**
     * Reports progress on a flow.
     */
    fun `progress`(`flowId`: kotlin.String, `step`: kotlin.String, `detail`: kotlin.String?)
    
    companion object
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}

